// Doctor-only evidence view for one case: recorded clinical evidence first, every AI output in one tab.
import { useState } from 'react'

import type { CaseReviewDto, MemberWorkspaceDto } from '../../services/apiClient'
import { AgentOutputCard } from './AgentOutputCard'
import { IconBrain, IconDna, IconStethoscope } from './ApprovalIcons'
import { findTrace, reviewReasons, statusLabel } from './approvalReview'
import { isNoDataTrace, isSyntheticTrace, NO_DATA_LABEL, traceConfidence } from './safetyRules'
import { ApprovalSupportingEvidence } from './ApprovalSupportingEvidence'
import { SafetyChecks } from './SafetyChecks'

type TabId = 'overview' | 'ai'

const tabs: Array<{ id: TabId; label: string }> = [
  { id: 'overview', label: 'Clinical overview' },
  { id: 'ai', label: 'AI analysis' },
]

export function ApprovalEvidenceTabs({ review, onWorkspace }: { review: CaseReviewDto; onWorkspace?: (workspace: MemberWorkspaceDto | null) => void }) {
  const [tab, setTab] = useState<TabId>('overview')
  const safetyTrace = findTrace(review.traces, 'safety')

  return (
    <>
      <div className="approval-tabs" role="tablist" aria-label="Case details">
        {tabs.map((item) => (
          <button
            key={item.id}
            type="button"
            role="tab"
            id={`approval-tab-${item.id}`}
            aria-selected={tab === item.id}
            aria-controls={`approval-panel-${item.id}`}
            className="approval-tab"
            onClick={() => setTab(item.id)}
          >
            {item.label}
          </button>
        ))}
      </div>

      <div role="tabpanel" id={`approval-panel-${tab}`} aria-labelledby={`approval-tab-${tab}`}>
        {tab === 'overview' && (
          <div className="approval-grid">
            <article className="care-panel approval-tile approval-tile--attention approval-tile--wide">
              <h3><IconStethoscope /> Why this case needs review</h3>
              <ul className="approval-reasons">
                {reviewReasons(review).map((reason) => (
                  <li key={reason}>{reason}</li>
                ))}
              </ul>
            </article>
            <ApprovalSupportingEvidence key={review.id} memberId={review.memberId} caseId={review.id} onWorkspace={onWorkspace} />
          </div>
        )}

        {tab === 'ai' && (
          <div className="approval-grid approval-grid--stack">
            <AgentOutputCard
              wide
              draft
              title="AI findings — plain language"
              icon={<IconBrain />}
              tag="Unapproved AI draft"
              raw={review.draftAdvisoryJson}
              empty="No AI draft advisory was produced for this request."
              caption="Not a diagnosis. Not visible to the patient."
            />
            <AgentOutputCard
              title="Context agent"
              trace={findTrace(review.traces, 'context')}
              raw={review.contextJson}
              empty="No structured context was available for this stage."
            />
            <AgentOutputCard
              title="Analysis agent"
              trace={findTrace(review.traces, 'analysis')}
              raw={review.analysisJson}
              empty="No structured analysis was available for this stage."
            />
            <AgentOutputCard
              title="Familial risk agent"
              icon={<IconDna />}
              trace={findTrace(review.traces, 'familial')}
              raw={review.familialRiskJson}
              empty="No consented family-history screening indication is available."
              caption="A screening indication only — never a diagnosis."
            />
            <AgentOutputCard
              title="Safety validation agent"
              trace={safetyTrace}
              raw={safetyTrace ? JSON.stringify(safetyTrace) : null}
              empty="The safety validation step did not record a trace."
              plain={<SafetyChecks traces={review.traces} review={review} />}
            />

            <article className="care-panel approval-tile approval-tile--wide">
              <h3>
                Technical audit trace <span className="status-badge status-badge--muted">Internal only</span>
              </h3>
              <p className="care-caption">
                For audit and troubleshooting. Trace steps: {review.traces.length} · Case status:{' '}
                {statusLabel(review.status)}
              </p>
              {review.traces.length > 0 && (
                <details><summary>View recorded audit steps</summary><div className="table-scroll">
                  <table>
                    <thead>
                      <tr>
                        <th scope="col">Step</th>
                        <th scope="col">Agent</th>
                        <th scope="col">Status</th>
                        <th scope="col">Confidence</th>
                        <th scope="col">Latency</th>
                        <th scope="col">Tools denied</th>
                      </tr>
                    </thead>
                    <tbody>
                      {review.traces.map((trace) => (
                        <tr key={trace.stepNumber}>
                          <td>{trace.stepNumber}</td>
                          <td>{statusLabel(trace.agent)}</td>
                          <td>{isSyntheticTrace(trace) ? `Synthetic demo · recorded ${statusLabel(trace.status)} · output unavailable` : isNoDataTrace(trace) ? NO_DATA_LABEL : trace.hasOutput === false ? `Output unavailable · recorded ${statusLabel(trace.status)}` : statusLabel(trace.status)}</td>
                          <td>{traceConfidence(trace)}</td>
                          <td>{trace.latencyMilliseconds} ms</td>
                          <td>{trace.toolsDenied.length}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div></details>
              )}
            </article>
          </div>
        )}
      </div>
    </>
  )
}
